import json,math,pathlib
r=.07/12;principal=27000;payment=principal*r/(1-(1+r)**-60);interest=payment*60-principal
costs=dict(depreciation=15000,interest=interest,tax=1800,insurance=12000,fuel=8400,maintenance=6000,registration=1250)
total=sum(costs.values());cash=total+15000
shots=[]
def s(kind,title,narration,**kw):shots.append(dict(id=len(shots)+1,kind=kind,title=title,narration=narration,**kw))
s('dealership','THE $30,000 CAR',"Alex just bought a thirty-thousand-dollar car. Nice color. Decent mileage. And a monthly payment that seems manageable. So, what does this car actually cost?",chapter='The price tag',mood='happy',amount=30000)
s('surprise','THE PRICE TAG IS ONLY THE START',"If your answer is thirty thousand dollars, the car would like a word. Because the price on the windshield is only the beginning of the story.",mood='surprised',amount=30000)
s('road','FIVE YEARS. ONE CAR. EVERY COST.',"We're going to follow Alex for five years. Through the loan, the gas station, the insurance bill, and the repair shop. Then we'll sell the car and count what ownership really cost.",chapter='The five-year plan',mood='happy')
s('assumptions','ONE EXAMPLE, NOT A NATIONAL AVERAGE',"This is an illustrative budget, not a quote or a national average. Your state, your driving, your insurance, and the car you choose can change every number. The useful part is the method.",mood='neutral')
s('dealership','A PAYMENT THAT LOOKS AFFORDABLE',"Back at the dealership, Alex sees the number that gets all the attention: about five hundred thirty-five dollars a month. That number is real. It just doesn't describe the whole car budget.",amount=535,mood='happy',variant='payment')
s('loan','HERE IS THE DEAL',"The purchase price is thirty thousand dollars. Alex puts three thousand down and borrows the remaining twenty-seven thousand, at seven percent A P R, for sixty months.",chapter='The loan',amount=27000,mood='neutral')
s('payment','ABOUT $535 A MONTH',"With a standard fixed-rate loan, that works out to about five hundred thirty-five dollars a month. Over five years, the loan payments add up to roughly thirty-two thousand seventy-eight dollars.",amount=535,mood='neutral')
s('interest','BORROW $27,000. REPAY ABOUT $32,078.',"Subtract the twenty-seven thousand borrowed, and about five thousand seventy-eight dollars is interest. That's the price of financing in this example. It doesn't buy extra car. It pays for borrowing the money.",amount=5078,mood='concerned')
s('term','A SMALLER PAYMENT CAN HIDE A LONGER LOAN',"A longer loan could make the monthly number smaller while increasing total interest, if the rate stays the same. So Alex needs to compare the rate and the term, not just the payment.",amount=60,mood='thinking')
s('tax','THE FIRST EXTRA BILL',"Before Alex even leaves, there's sales tax. Let's assume six percent, or eighteen hundred dollars, paid upfront. We'll also budget two hundred fifty dollars a year for registration and related recurring fees.",chapter='The costs that follow',amount=1800,mood='surprised')
s('receipt','UPFRONT CASH: $4,800',"That means the three-thousand-dollar down payment isn't the only upfront cash. Add the assumed sales tax, and Alex needs forty-eight hundred dollars before the regular monthly bills even begin.",amount=4800,mood='concerned')
s('insurance','THE CAR HAS A SUBSCRIPTION',"First stop: insurance. We're giving Alex an assumed quote of two hundred dollars a month. That's twenty-four hundred a year, or twelve thousand dollars across five years, if the premium stays the same.",amount=200,mood='surprised')
s('shield','GET THE QUOTE BEFORE YOU BUY',"Insurance can vary dramatically by driver, location, coverage, and vehicle. A car with an affordable payment can come with an uncomfortable premium. Get a quote for the actual model before signing.",mood='thinking')
s('gas','NEXT STOP: THE GAS STATION',"Alex drives twelve hundred miles each month. At thirty miles per gallon, that's forty gallons. Assume gas averages three dollars and fifty cents a gallon, and fuel costs one hundred forty dollars a month.",amount=140,mood='neutral')
s('fuelmath','$140 A MONTH BECOMES $8,400',"Keep those assumptions for sixty months, and the fuel total is eighty-four hundred dollars. The gas pump doesn't care that the car payment already came out of Alex's account this morning.",amount=8400,mood='concerned')
s('garage','THE CAR NEEDS MORE THAN GAS',"Then come oil changes, tires, maintenance, and repairs. We'll set aside one hundred dollars a month. Some months cost almost nothing. Other months, the car introduces you to a very expensive noise.",amount=100,mood='surprised')
s('reserve','A RESERVE, NOT A PREDICTION',"That maintenance reserve totals six thousand dollars over five years. It's a planning assumption, not a promise. An unused reserve is still your money; an actual repair bill could be larger. We'll assume the full reserve is spent.",amount=6000,mood='thinking')
s('monthly','THE MONTHLY BILLS ADD UP',"Now look at Alex's monthly cash budget. About five hundred thirty-five for the loan. Two hundred for insurance. One hundred forty for fuel. One hundred for maintenance. Plus roughly twenty-one for annual registration.",chapter='The monthly reality',amount=995,mood='concerned')
s('monthlytotal','ABOUT $995 A MONTH',"That's about nine hundred ninety-five dollars a month, before the upfront down payment and sales tax. Suddenly, the five-hundred-thirty-five-dollar payment looks more like one piece of a much bigger puzzle.",amount=995,mood='surprised')
s('extras','YOUR ROUTE MAY ADD MORE',"And this budget still leaves out parking, tolls, tickets, and the return Alex might have earned on money used for the car. Your own version may need extra lines. Don't hide them just because they aren't monthly.",mood='thinking')
s('calendar','FIVE YEARS LATER',"Fast forward five years. Alex has made the payments and kept the car running. The loan is gone. But before we total the cost, there's one more number we need: what the car is worth now.",chapter='The value you keep',mood='happy')
s('depreciation','THE CAR IS NOW WORTH $15,000',"Let's assume Alex can sell it for fifteen thousand dollars. That's a scenario assumption, not a resale forecast. Some cars hold value better. Others lose more, especially with higher mileage or poor condition.",amount=15000,mood='thinking')
s('valuefall','$30,000 → $15,000',"The difference between the thirty-thousand-dollar purchase price and the fifteen-thousand-dollar sale price is fifteen thousand dollars. That's depreciation: the value Alex used up while owning the car.",amount=15000,mood='concerned')
s('invisible','NO MONTHLY BILL. STILL A REAL COST.',"Depreciation doesn't send an invoice every month. That's why it's easy to overlook. But when Alex sells, the missing value becomes very real. It's part of what those five years of driving cost.",amount=15000,mood='surprised')
s('nodouble','COUNT THE PURCHASE ONLY ONCE',"Here's where car-cost math often goes wrong. You cannot add every loan payment and then add depreciation on top. The principal in the payments already pays for the car. Counting both would count that purchase twice.",chapter='The true total',mood='thinking')
s('cashout','FIRST, COUNT THE CASH THAT LEFT',"One clean method is to track cash. Add the down payment, all sixty loan payments, sales tax, insurance, fuel, maintenance, and registration. For Alex, that's about sixty-four thousand five hundred twenty-eight dollars paid out.",amount=64528,mood='concerned')
s('resale','THEN SUBTRACT WHAT COMES BACK',"Now subtract the fifteen thousand dollars Alex receives from selling the car. That money comes back. The remaining cost is about forty-nine thousand five hundred twenty-eight dollars for five years of ownership.",amount=49528,mood='surprised')
s('total','THE $30,000 CAR COST ABOUT $49,500',"Round it, and this thirty-thousand-dollar car cost about forty-nine thousand five hundred dollars to own for five years. That's about eight hundred twenty-five dollars a month, averaged across the full period.",amount=49500,mood='surprised')
s('whyaverage','AVERAGE COST IS NOT THE MONTHLY BILL',"Why is that lower than the roughly nine-hundred-ninety-five-dollar monthly cash budget? Because the ownership average accounts for upfront costs and the car's resale value. Cash flow and total ownership cost answer different questions.",amount=825,mood='thinking')
s('ledger','ANOTHER WAY TO REACH THE SAME TOTAL',"You can also add depreciation, interest, and the operating costs directly. Fifteen thousand in lost value. About five thousand seventy-eight in interest. Then tax, insurance, fuel, maintenance, and registration. Same answer. No double counting.",amount=49528,mood='neutral')
s('stack','THE BIGGEST LINE ISN’T ALWAYS THE LOUDEST',"In this example, depreciation and insurance are bigger than fuel. Gas prices get a lot of attention because you see them every week. The costs you notice most aren't always the ones that matter most.",mood='thinking')
s('sensitivity','SMALL CHANGES BECOME BIG NUMBERS',"An insurance quote that's one hundred dollars more per month adds six thousand dollars over five years. A resale price three thousand dollars lower adds three thousand to ownership cost. Small assumptions deserve a second look.",chapter='How Alex can use this',amount=6000,mood='surprised')
s('choices','SO, SHOULD ALEX SKIP THE CAR?',"Does that mean Alex shouldn't own a car? No. A car can make work possible, save time, and connect you to people you care about. Knowing the cost helps you decide what that access is worth.",mood='happy')
s('comparecars','COMPARE MORE THAN THE STICKER PRICE',"It also makes comparisons fairer. A cheaper car may need more repairs. A newer car may lose more value. An electric car changes fuel and charging costs. The winner depends on the full set of assumptions.",mood='thinking')
s('used','WHAT IF THE CAR COST $20,000?',"For example, a twenty-thousand-dollar car, with the same three thousand down, seven percent rate, and sixty-month term, has a payment around three hundred thirty-seven dollars. That's roughly one hundred ninety-eight less each month.",amount=337,mood='happy')
s('tradeoff','A LOWER PAYMENT IS A STARTING POINT',"That lower payment is useful breathing room. It isn't a complete comparison yet. Alex still needs estimates for insurance, repairs, fuel, and resale value. Run the same five-year calculation for both cars.",mood='thinking')
s('checklist','BEFORE YOU SIGN: GET THE REAL NUMBERS',"Before signing, get the out-the-door price, the full loan terms, and an insurance quote. Estimate your actual mileage. Budget for maintenance. Then choose a reasonable ownership period and a conservative resale assumption.",chapter='Before you buy',mood='neutral')
s('twobudgets','ASK TWO DIFFERENT QUESTIONS',"Make two budgets. First: can I handle the cash payments, including the upfront money and occasional large bills? Second: what will owning this car cost over the years I expect to keep it?",mood='thinking')
s('paidcash','PAYING CASH DOESN’T REMOVE EVERY COST',"Paying cash removes loan interest in this example. It doesn't remove depreciation, insurance, fuel, taxes, or repairs. And the money you tie up in the car still has other possible uses.",mood='neutral')
s('keep','PAID OFF IS NOT THE SAME AS FREE',"Keeping a paid-off car can reduce your budget pressure, too. But keep allowing for maintenance and value loss. A zero-dollar loan payment feels great. It doesn't turn the rest of the dashboard into zeroes.",mood='happy')
s('ending','A BETTER QUESTION THAN “CAN I AFFORD IT?”',"Alex still likes the blue car. Now, though, the decision comes with open eyes. Instead of asking only, can I afford this payment, Alex asks: what will this car really cost me to own?",chapter='The takeaway',mood='happy')
s('final','UNDERSTAND THE WHOLE BILL.',"Before your next test drive, build the whole budget. Because the number on the windshield tells you what you're buying. The full cost tells you what you're committing to.",mood='happy')
# Editorial cut: retain distinct story beats and avoid repeating the same cost lesson.
shots=[s for s in shots if s['id'] not in {9,17,20,24,31,39}]
for s in shots:
 if s['id']==16:s['narration']="Then come oil changes, tires, maintenance, and repairs. We'll budget one hundred dollars a month, and assume six thousand dollars is actually spent over five years. Some months are quiet. Other months, the car makes a very expensive noise."
pathlib.Path('script.json').write_text(json.dumps(shots,indent=2))
pathlib.Path('work/model.json').write_text(json.dumps(dict(price=30000,down_payment=3000,principal=principal,apr=.07,months=60,payment=payment,interest=interest,costs=costs,total_cost=total,cash_out=cash,resale=15000,monthly_average=total/60,monthly_cash=payment+200+140+100+250/12),indent=2))
pathlib.Path('script.en.txt').write_text('\n\n'.join(x['narration'] for x in shots))
